14	declare_lint_rule! {
15	    /// Disallow ambiguous anchor descriptions.
16	    ///
17	    /// Enforces `<a>` values are not exact matches for the phrases "click here", "here", "link", "a link", or "learn more".
18	    /// Screen readers announce tags as links/interactive, but rely on values for context.
19	    /// Ambiguous anchor descriptions do not provide sufficient context for users.
20	    ///
21	    /// ## Examples
22	    ///
23	    /// ### Invalid
24	    ///
25	    /// ```jsx,expect_diagnostic
26	    /// const Invalid = () => <a>learn more</a>;
27	    /// ```
28	    ///
29	    /// ### Valid
30	    ///
31	    /// ```jsx
32	    /// const Valid = () => <a>documentation</a>;
33	    /// ```
34	    ///
35	    /// ## Options
36	    ///
37	    /// ### `words`
38	    ///
39	    /// The words option allows users to modify the strings that can be checked for in the anchor text. Useful for specifying other words in other languages.
40	    ///
41	    /// Default `["click here", "here", "link", "a link", "learn more"]`
42	    ///
43	    /// ```json,options
44	    /// {
45	    ///   "options": {
46	    ///     "words": ["click this"]
47	    ///   }
48	    /// }
49	    /// ```
50	    ///
51	    /// #### Invalid
52	    ///
53	    /// ```jsx,expect_diagnostic,use_options
54	    /// const Invalid = () => <a>click this</a>;
55	    /// ```
56	    ///
57	    pub NoAmbiguousAnchorText {
58	        version: "2.3.10",
59	        name: "noAmbiguousAnchorText",
60	        language: "js",
61	        recommended: false,
62	        sources: &[RuleSource::EslintJsxA11y("anchor-ambiguous-text").same()],
63	    }
64	}
