14	    /// Prevent comments from being inserted as text nodes
15	    ///
16	    /// ## Examples
17	    ///
18	    /// ### Invalid
19	    ///
20	    /// ```jsx,expect_diagnostic
21	    /// <div>// comment</div>;
22	    /// ```
23	    ///
24	    /// ```jsx,expect_diagnostic
25	    /// <div>/* comment */</div>;
26	    /// ```
27	    ///
28	    /// ```jsx,expect_diagnostic
29	    /// <div>/** comment */</div>;
30	    /// ```
31	    ///
32	    /// ```jsx,expect_diagnostic
33	    /// <div>text /* comment */</div>;
34	    /// ```
35	    ///
36	    /// ```jsx,expect_diagnostic
37	    /// <div>/* comment */ text</div>;
38	    /// ```
39	    ///
40	    /// ```jsx,expect_diagnostic
41	    /// <div>
42	    ///     text
43	    ///     // comment
44	    /// </div>;
45	    /// ```
46	    ///
47	    /// ```jsx,expect_diagnostic
48	    /// <div>
49	    ///     // comment
50	    ///    text
51	    /// </div>;
52	    /// ```
53	    ///
54	    /// ```jsx,expect_diagnostic
55	    /// <div>
56	    ///     /* comment */
57	    ///     text
58	    /// </div>;
59	    /// ```
60	    ///
61	    /// ### Valid
62	    ///
63	    /// ```jsx
64	    /// <>
65	    ///    <div>{/* comment */}</div>;
66	    ///    <div>{/** comment */}</div>;
67	    ///    <div className={"cls" /* comment */}></div>;
68	    ///    <div>text {/* comment */}</div>;
69	    ///    <div>{/* comment */} text</div>;
70	    /// </>
71	    /// ```
72	    pub NoCommentText {
73	        version: "1.0.0",
74	        name: "noCommentText",
75	        language: "jsx",
76	        sources: &[RuleSource::EslintReact("jsx-no-comment-textnodes").same()],
77	        recommended: true,
78	        severity: Severity::Error,
79	        fix_kind: FixKind::Unsafe,
