83	impl Rule for NoCommentText {
84	    type Query = Ast<JsxText>;
85	    type State = Range<usize>;
86	    type Signals = Option<Self::State>;
87	    type Options = NoCommentTextOptions;
88	
89	    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
90	        let node = ctx.query();
91	        let jsx_value = node.value_token().ok()?;
92	        let jsx_value = jsx_value.text();
93	        let bytes = jsx_value.as_bytes();
94	        let mut bytes_iter = jsx_value.bytes().enumerate();
95	        while let Some((index, byte)) = bytes_iter.next() {
96	            if byte != b'/' {
97	                continue;
98	            }
99	            match bytes_iter.next()? {
100	                (_, b'/') => {
101	                    // Ignore `://` (`https://`, ...)
102	                    if index == 0 || bytes.get(index - 1) != Some(&b':') {
103	                        let end = bytes_iter
104	                            .find(|(_, c)| c == &b'\n')
105	                            .map_or(bytes.len(), |(index, _)| index);
106	                        return Some(index..end);
107	                    }
108	                }
109	                (_, b'*') => {
110	                    let mut end = 0;
111	                    while let Some((_, byte)) = bytes_iter.next() {
112	                        if byte != b'*' {
113	                            continue;
114	                        }
115	                        let Some((index, b'/')) = bytes_iter.next() else {
116	                            continue;
117	                        };
118	                        end = index + 1;
119	                        break;
120	                    }
121	                    if end > 0 {
122	                        return Some(index..end);
123	                    }
124	                }
125	                _ => {}
126	            }
127	        }
128	        None
129	    }
130	
131	    fn diagnostic(ctx: &RuleContext<Self>, range: &Self::State) -> Option<RuleDiagnostic> {
132	        let node_range_start = ctx.query().value_token().ok()?.text_range().start();
133	        Some(RuleDiagnostic::new(
134	            rule_category!(),
135	            TextRange::new(
136	                node_range_start + TextSize::from(range.start as u32),
137	                node_range_start + TextSize::from(range.end as u32),
138	            ),
139	            markup! {
140	                "Wrap "<Emphasis>"comments"</Emphasis>" inside children within "<Emphasis>"braces"</Emphasis>"."
141	            },
142	        ))
143	    }
144	
145	    fn action(ctx: &RuleContext<Self>, range: &Self::State) -> Option<JsRuleAction> {
146	        let node = ctx.query();
147	        let jsx_value = node.value_token().ok()?;
148	        let jsx_value = jsx_value.text();
149	        let before_comment = &jsx_value[..range.start];
150	        let after_comment = &jsx_value[range.end..];
151	        let new_jsx_value = if jsx_value.as_bytes()[range.start + 1] == b'*' {
152	            let comment = &jsx_value[range.start..range.end];
153	            format!("{before_comment}{{{comment}}}{after_comment}")
154	        } else {
155	            let comment_text = &jsx_value[range.start + 2..range.end].trim();
156	            format!("{before_comment}{{/* {comment_text} */}}{after_comment}")
157	        };
158	        let new_jsx_text = AnyJsxChild::JsxText(make::jsx_text(JsSyntaxToken::new_detached(
159	            JsSyntaxKind::JSX_TEXT,
160	            &new_jsx_value,
161	            [],
162	            [],
163	        )));
164	        let mut mutation = ctx.root().begin();
165	        mutation.replace_node(AnyJsxChild::from(node.clone()), new_jsx_text);
166	        Some(JsRuleAction::new(
167	            ctx.metadata().action_category(ctx.category(), ctx.group()),
168	            ctx.metadata().applicability(),
169	            markup! { "Wrap the comments with braces" }.to_owned(),
170	            mutation,
171	        ))
172	    }
173	}
