use biome_rule_options::no_jsx_leaked_dollar::NoJsxLeakedDollarOptions;

declare_lint_rule! {
    /// Disallow a stray `$` at the end of a JSX text node that is immediately followed by a JSX expression.
    ///
    /// When migrating from template literals to JSX, it is easy to leave behind a `$`
    /// before a `{expression}`. Unlike in a template literal, this `$` is rendered as
    /// literal text instead of being part of an interpolation.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```jsx,expect_diagnostic
    /// <div>Total: cost${price}</div>;
    /// ```
    ///
    /// ### Valid
    ///
    /// ```jsx
    /// <div>Total: {price}</div>;
    /// ```
    ///
    /// A lone `$` before a single expression is considered intentional, for example when
    /// displaying a currency value:
    ///
    /// ```jsx
    /// <div>${price}</div>;
    /// ```
    ///
    pub NoJsxLeakedDollar {
        version: "next",
        name: "noJsxLeakedDollar",
        language: "jsx",
        recommended: false,
        severity: Severity::Warning,
        fix_kind: FixKind::Unsafe,
    }
}

impl Rule for NoJsxLeakedDollar {
    type Query = Ast<JsxText>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoJsxLeakedDollarOptions;

    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let text = token.text();
        if !text.ends_with('$') {
            return None;
        }

        // The immediately following sibling must be a JSX expression child (`{...}`).
        let next = node.syntax().next_sibling()?;
        if next.kind() != JsSyntaxKind::JSX_EXPRESSION_CHILD {
            return None;
        }

        // A lone `$` before a single expression is treated as intentional (e.g. a
        // currency value), when it is the only text preceding the only expression.
        if text == "$" {
            if let Some(list) = node.syntax().parent().and_then(JsxChildList::cast) {
                if list.len() == 2 {
                    return None;
                }
            }
        }

        Some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let end = token.text_range().end();
        let dollar_range = TextRange::new(end - TextSize::from(1), end);
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                dollar_range,
                markup! {
                    "Possible unintentional '$' before a JSX expression."
                },
            )
            .note(markup! {
                "This '$' will be rendered as text. Remove the '$' from the text node or add a suppression if it is intentional."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<JsRuleAction> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let text = token.text();
        // Remove only the trailing `$`, leaving the rest of the text intact.
        let new_text = &text[..text.len() - 1];
        let new_jsx_text = AnyJsxChild::JsxText(make::jsx_text(JsSyntaxToken::new_detached(
            JsSyntaxKind::JSX_TEXT,
            new_text,
            [],
            [],
        )));
        let mut mutation = ctx.root().begin();
        mutation.replace_node(AnyJsxChild::from(node.clone()), new_jsx_text);
        Some(JsRuleAction::new(
            ctx.metadata().action_category(ctx.category(), ctx.group()),
            ctx.metadata().applicability(),
            markup! { "Remove dollar sign." }.to_owned(),
            mutation,
        ))
    }
}
